WITH objRec AS ( SELECT tmp3.PROD_ID, tmp3.VDATE, tmp3.RAISE_QTY, tmp3.TOTAL_AMT FROM ( SELECT tmp2.PROD_ID, tmp2.VDATE, B.RAISE_QTY, B.TOTAL_AMT, ROW_NUMBER() over( partition by tmp2.PROD_ID ORDER BY B.STATUS DESC ,B.UPDATE_TIME DESC) AS raiseStatusNo FROM ( SELECT A.PROD_ID, A.VDATE FROM CHB_PRD_BASEINFO A LEFT JOIN ( SELECT PROD_ID, MAX(MDATE) FROM CHB_PRD_DEAL_SUB WHERE STATUS IN ('01','02') AND STR_TO_DATE(DATE_FORMAT(MDATE, '%Y-%m-%d'), '%Y-%m-%d') <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') GROUP BY PROD_ID ) tmp1 ON A.PROD_ID = tmp1.PROD_ID WHERE tmp1.PROD_ID is null AND A.FPROD_ID is null AND A.STATUS != 'D'
#{orgCode,jdbcType=VARCHAR}
) tmp2 INNER JOIN CHB_PRD_RAISETOT_SUB B ON (tmp2.PROD_ID = B.PROD_ID AND STATUS IN ('01','02')) ) tmp3 WHERE raiseStatusNo = 1 )
